/**
 * Pre-recorded ElevenLabs clips for the hosted build (generated by scripts/render-voice-pack.ts).
 * Absent → empty; the page then uses the browser's voice.
 */
const files = import.meta.glob<{ default: { voiceId: string; clips: Record<string, string> } }>('../../voice-pack/pack.json', { eager: true });
const pack = Object.values(files)[0]?.default;

export const voiceClips: Record<string, string> = pack?.clips ?? {};
export const hasVoicePack = Object.keys(voiceClips).length > 0;

/** The recorded lines available for a persona (for Claude to choose from). */
export function recordedLinesFor(persona: string): string[] {
  return Object.keys(voiceClips)
    .filter((k) => k.startsWith(`${persona}|`))
    .map((k) => k.slice(persona.length + 1));
}
